import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class SafeResourceTransfer {
    private final Lock lockA = new ReentrantLock();
    private final Lock lockB = new ReentrantLock();

    public boolean transfer(long timeoutMillis) throws InterruptedException {
        long stopTime = System.currentTimeMillis() + timeoutMillis;
        while (System.currentTimeMillis() < stopTime) {
            if (lockA.tryLock(50, TimeUnit.MILLISECONDS)) {
                try {
                    if (lockB.tryLock(50, TimeUnit.MILLISECONDS)) {
                        try {
                            // Critical section execution
                            return true;
                        } finally {
                            lockB.unlock();
                        }
                    }
                } finally {
                    lockA.unlock();
                }
            }
            // Randomized exponential backoff to prevent livelock/starvation collision loops
            Thread.sleep((long) (Math.random() * 100));
        }
        return false;
    }
}
